import {
  type FocusEvent,
  type KeyboardEvent,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from 'react';

export interface NameComboboxOption {
  description?: string;
  keywords?: string[];
  label: string;
  value: string;
}

interface NameComboboxProps {
  dependencyKey: string;
  entityName: string;
  inputValue: string;
  label: string;
  loadOptions(signal: AbortSignal): Promise<NameComboboxOption[]>;
  onInputChange(value: string): void;
  onSelectionChange(option: NameComboboxOption | null): void;
  onSelectionResolved(option: NameComboboxOption | null): void;
  placeholder?: string | undefined;
  selectedValue: string;
  validationMessage?: string | undefined;
}

type OptionsState =
  | { status: 'idle'; options: NameComboboxOption[] }
  | { status: 'loading'; options: NameComboboxOption[] }
  | { status: 'ready'; options: NameComboboxOption[] }
  | { status: 'error'; options: NameComboboxOption[] };

function normalizedText(value: string): string {
  return value
    .toLocaleLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');
}

function scoreText(value: string, query: string): number | null {
  const normalizedValue = normalizedText(value);
  const normalizedQuery = normalizedText(query.trim());

  if (!normalizedQuery) {
    return 0;
  }

  if (normalizedValue === normalizedQuery) {
    return 10_000;
  }

  if (normalizedValue.startsWith(normalizedQuery)) {
    return 8_000 - normalizedValue.length;
  }

  const wordIndex = normalizedValue.search(new RegExp(`(?:^|\\s)${escapeRegExp(normalizedQuery)}`));
  if (wordIndex >= 0) {
    return 7_000 - wordIndex;
  }

  const substringIndex = normalizedValue.indexOf(normalizedQuery);
  if (substringIndex >= 0) {
    return 6_000 - substringIndex;
  }

  let valueIndex = 0;
  let previousMatch = -2;
  let score = 1_000;

  for (const character of normalizedQuery) {
    const matchIndex = normalizedValue.indexOf(character, valueIndex);
    if (matchIndex < 0) {
      return null;
    }

    score += matchIndex === previousMatch + 1 ? 20 : 5;
    score -= matchIndex - valueIndex;
    previousMatch = matchIndex;
    valueIndex = matchIndex + 1;
  }

  return score - normalizedValue.length;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export function fuzzyRankOptions(
  options: NameComboboxOption[],
  query: string,
): NameComboboxOption[] {
  return options
    .map((option) => {
      const scores = [option.label, ...(option.keywords ?? [])]
        .map((value) => scoreText(value, query))
        .filter((score): score is number => score !== null);

      return {
        option,
        score: scores.length > 0 ? Math.max(...scores) : null,
      };
    })
    .filter(
      (candidate): candidate is { option: NameComboboxOption; score: number } =>
        candidate.score !== null,
    )
    .sort(
      (left, right) =>
        right.score - left.score || left.option.label.localeCompare(right.option.label),
    )
    .map(({ option }) => option);
}

export function NameCombobox({
  dependencyKey,
  entityName,
  inputValue,
  label,
  loadOptions,
  onInputChange,
  onSelectionChange,
  onSelectionResolved,
  placeholder,
  selectedValue,
  validationMessage,
}: NameComboboxProps) {
  const generatedId = useId();
  const inputId = `name-combobox-${generatedId}`;
  const listboxId = `${inputId}-listbox`;
  const feedbackId = `${inputId}-feedback`;
  const wrapperRef = useRef<HTMLDivElement>(null);
  const loadedDependencyKeyRef = useRef<string | null>(null);
  const onSelectionResolvedRef = useRef(onSelectionResolved);
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [requestVersion, setRequestVersion] = useState(0);
  const [state, setState] = useState<OptionsState>({ status: 'idle', options: [] });
  const shouldLoad =
    (open && loadedDependencyKeyRef.current !== dependencyKey) ||
    (Boolean(selectedValue) && (state.status === 'idle' || state.status === 'loading'));

  useEffect(() => {
    onSelectionResolvedRef.current = onSelectionResolved;
  }, [onSelectionResolved]);

  useEffect(() => {
    if (!shouldLoad) {
      return;
    }

    const controller = new AbortController();
    setState((current) => ({ status: 'loading', options: current.options }));

    void loadOptions(controller.signal)
      .then((options) => {
        if (controller.signal.aborted) {
          return;
        }

        loadedDependencyKeyRef.current = dependencyKey;
        setState({ status: 'ready', options });
        if (selectedValue) {
          onSelectionResolvedRef.current(
            options.find((option) => option.value === selectedValue) ?? null,
          );
        }
      })
      .catch(() => {
        if (!controller.signal.aborted) {
          setState((current) => ({ status: 'error', options: current.options }));
        }
      });

    return () => controller.abort();
  }, [dependencyKey, loadOptions, requestVersion, selectedValue, shouldLoad]);

  useEffect(() => {
    if (!open) {
      return;
    }

    function dismiss(event: PointerEvent) {
      if (!wrapperRef.current?.contains(event.target as Node)) {
        setOpen(false);
        setActiveIndex(-1);
      }
    }

    document.addEventListener('pointerdown', dismiss);
    return () => document.removeEventListener('pointerdown', dismiss);
  }, [open]);

  const selectedOption = state.options.find((option) => option.value === selectedValue);
  const searchQuery = selectedOption?.label === inputValue ? '' : inputValue;
  const rankedOptions = useMemo(
    () => fuzzyRankOptions(state.options, searchQuery),
    [searchQuery, state.options],
  );
  const activeOption = activeIndex >= 0 ? rankedOptions[activeIndex] : undefined;

  function showOptions() {
    setOpen(true);
    setActiveIndex(-1);
  }

  function choose(option: NameComboboxOption) {
    onSelectionChange(option);
    setOpen(false);
    setActiveIndex(-1);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape' && open) {
      event.preventDefault();
      setOpen(false);
      setActiveIndex(-1);
      return;
    }

    if (event.key === 'Tab') {
      setOpen(false);
      setActiveIndex(-1);
      return;
    }

    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      showOptions();
      if (rankedOptions.length > 0) {
        setActiveIndex((current) => {
          if (event.key === 'ArrowDown') {
            return current < rankedOptions.length - 1 ? current + 1 : 0;
          }
          return current > 0 ? current - 1 : rankedOptions.length - 1;
        });
      }
      return;
    }

    if (event.key === 'Home' && open && rankedOptions.length > 0) {
      event.preventDefault();
      setActiveIndex(0);
      return;
    }

    if (event.key === 'End' && open && rankedOptions.length > 0) {
      event.preventDefault();
      setActiveIndex(rankedOptions.length - 1);
      return;
    }

    if (event.key === 'Enter' && open && activeOption) {
      event.preventDefault();
      choose(activeOption);
    }
  }

  function handleBlur(event: FocusEvent<HTMLDivElement>) {
    if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
      setOpen(false);
      setActiveIndex(-1);
    }
  }

  const announcement = (() => {
    if (!open) {
      return selectedOption ? `${selectedOption.label} selected.` : '';
    }
    if (state.status === 'loading') {
      return `Loading ${entityName} options.`;
    }
    if (state.status === 'error') {
      return `${label} options could not be loaded.`;
    }
    if (state.status === 'ready' && rankedOptions.length === 0) {
      return `No matching ${entityName} options.`;
    }
    if (state.status === 'ready') {
      return `${rankedOptions.length} ${entityName} ${rankedOptions.length === 1 ? 'option' : 'options'} available.`;
    }
    return '';
  })();

  return (
    <div className="field name-combobox" onBlur={handleBlur} ref={wrapperRef}>
      <label htmlFor={inputId}>{label}</label>
      <div className="name-combobox__control">
        <input
          aria-activedescendant={activeOption ? `${listboxId}-${activeIndex}` : undefined}
          aria-autocomplete="list"
          aria-controls={listboxId}
          aria-describedby={validationMessage ? feedbackId : undefined}
          aria-expanded={open}
          aria-haspopup="listbox"
          aria-invalid={validationMessage ? 'true' : undefined}
          autoComplete="off"
          id={inputId}
          onChange={(event) => {
            onInputChange(event.target.value);
            showOptions();
          }}
          onFocus={() => {
            if (open) {
              showOptions();
            }
          }}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          role="combobox"
          type="text"
          value={inputValue}
        />
        {selectedValue ? (
          <button
            aria-label={`Clear ${label.toLocaleLowerCase()}`}
            className="name-combobox__clear"
            onClick={() => {
              onSelectionChange(null);
              setOpen(false);
            }}
            type="button"
          >
            Clear
          </button>
        ) : null}
        <button
          aria-label={`${open ? 'Hide' : 'Show'} ${label.toLocaleLowerCase()} options`}
          aria-expanded={open}
          className="name-combobox__toggle"
          onClick={() => {
            if (open) {
              setOpen(false);
              setActiveIndex(-1);
            } else {
              showOptions();
            }
          }}
          type="button"
        >
          <span aria-hidden="true">{open ? 'â–´' : 'â–¾'}</span>
        </button>
      </div>

      {validationMessage ? (
        <p className="field-error" id={feedbackId}>
          {validationMessage}
        </p>
      ) : null}

      <span aria-live="polite" className="visually-hidden">
        {announcement}
      </span>

      {open ? (
        <div className="name-combobox__popover">
          {state.status === 'loading' ? (
            <p className="name-combobox__state" role="status">
              Loading {entityName} optionsâ€¦
            </p>
          ) : null}

          {state.status === 'error' ? (
            <div className="name-combobox__state name-combobox__state--error" role="alert">
              <p>{label} options could not be loaded.</p>
              <button
                className="button button--secondary"
                onClick={() => setRequestVersion((version) => version + 1)}
                type="button"
              >
                Retry {entityName} options
              </button>
            </div>
          ) : null}

          {state.status === 'ready' && rankedOptions.length === 0 ? (
            <p className="name-combobox__state" role="status">
              No matching {entityName} options.
            </p>
          ) : null}

          {state.status === 'ready' && rankedOptions.length > 0 ? (
            <ul
              aria-label={`${label} options`}
              className="name-combobox__options"
              id={listboxId}
              role="listbox"
            >
              {rankedOptions.map((option, index) => (
                <li
                  aria-selected={option.value === selectedValue}
                  className={
                    index === activeIndex
                      ? 'name-combobox__option is-active'
                      : 'name-combobox__option'
                  }
                  id={`${listboxId}-${index}`}
                  key={option.value}
                  onClick={() => choose(option)}
                  onMouseDown={(event) => event.preventDefault()}
                  onMouseEnter={() => setActiveIndex(index)}
                  role="option"
                >
                  <span>{option.label}</span>
                  {option.description ? <small>{option.description}</small> : null}
                  {option.value === selectedValue ? (
                    <small className="name-combobox__selected-marker">Selected</small>
                  ) : null}
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}
--- backend controller relevant ---
import {
  competitionListQuerySchema,
  competitorListQuerySchema,
  FIXTURE_EVENT_EXPORT_LIMIT,
  fixtureEventExportQuerySchema,
  fixtureEventListQuerySchema,
  fixtureListQuerySchema,
  participantFixtureListQuerySchema,
  participantListQuerySchema,
  seasonListQuerySchema,
} from '@sport-analytics/contracts';
import type { PublicEvent } from '@sport-analytics/contracts';
import type { Request, RequestHandler, Response } from 'express';
import type { z } from 'zod';

import { PublicReadInputError } from './public-read.errors';
import type { PublicReadService } from './public-read.service';

const fixtureEventCsvColumns = [
  'eventId',
  'fixtureId',
  'inningsId',
  'inningsOrdinal',
  'sequenceNumber',
  'overNumber',
  'positionInOver',
  'ballNumber',
  'battingCompetitorId',
  'bowlingCompetitorId',
  'strikerParticipantId',
  'nonStrikerParticipantId',
  'bowlerParticipantId',
  'runsOffBat',
  'runsExtras',
  'runsTotal',
  'runsNonBoundary',
  'extrasWides',
  'extrasNoBalls',
  'extrasByes',
  'extrasLegByes',
  'extrasPenalty',
  'wicketCount',
  'wicketIds',
  'wicketKinds',
  'playersOutParticipantIds',
  'fielderParticipantIds',
] as const;

type AsyncHandler = (request: Request, response: Response) => Promise<void>;

function wrapPublicHandler(handler: AsyncHandler): RequestHandler {
  return (request, response, next) => {
    void handler(request, response).catch((error) => {
      if (error instanceof PublicReadInputError) {
        response.status(400).json({
          error: {
            code: error.code,
            message: error.message,
          },
        });
        return;
      }

      next(error);
    });
  };
}

function parseQuery<S extends z.ZodTypeAny>(
  schema: S,
  request: Request,
  response: Response,
): z.output<S> | undefined {
  const result = schema.safeParse(request.query);
  if (result.success) {
    return result.data;
  }

  response.status(400).json({
    error: {
      code: 'VALIDATION_FAILED',
      message: 'The request is invalid.',
      details: result.error.issues.map((issue) => ({
        code: 'INVALID_FIELD',
        message: issue.message,
        ...(issue.path.length > 0
          ? {
              field: issue.path.join('.'),
            }
          : {}),
      })),
    },
  });

  return undefined;
}
function getPathParameter(request: Request, name: string): string {
  const value = request.params[name];

  if (value === undefined) {
    throw new Error(`Expected route parameter "${name}" was not provided.`);
  }

  return value;
}

function sendNotFound(response: Response, resource: string): void {
  response.status(404).json({
    error: {
      code: 'NOT_FOUND',
      message: `${resource} not found.`,
    },
  });
}

function escapeCsvCell(value: boolean | number | string | null): string {
  let text = value === null ? '' : String(value);

  // Prevent spreadsheet applications from interpreting public text as a formula.
  if (/^[=+\-@]/.test(text)) {
    text = `'${text}`;
  }

  return `"${text.replaceAll('"', '""')}"`;
}

function serializeFixtureEventsCsv(events: PublicEvent[]): string {
  const rows = events.map((event) => {
    const wickets = event.wickets;
    const fielderParticipantIds = wickets.flatMap((wicket) =>
      wicket.fielders.flatMap((fielder) =>
        fielder.participantId === null ? [] : [fielder.participantId],
      ),
    );

    const values: Array<boolean | number | string | null> = [
      event.eventId,
      event.fixtureId,
      event.inningsId,
      event.inningsOrdinal,
      event.sequenceNumber,
      event.overNumber,
      event.positionInOver,
      event.ballNumber,
      event.battingCompetitorId,
      event.bowlingCompetitorId,
      event.strikerParticipantId,
      event.nonStrikerParticipantId,
      event.bowlerParticipantId,
      event.runs.offBat,
      event.runs.extras,
      event.runs.total,
      event.runs.nonBoundary,
      event.extras.wides,
      event.extras.noBalls,
      event.extras.byes,
      event.extras.legByes,
      event.extras.penalty,
      wickets.length,
      wickets.map((wicket) => wicket.wicketId).join('|'),
      wickets.map((wicket) => wicket.kind).join('|'),
      wickets.map((wicket) => wicket.playerOutParticipantId).join('|'),
      fielderParticipantIds.join('|'),
    ];

    return values.map(escapeCsvCell).join(',');
  });

  return [fixtureEventCsvColumns.join(','), ...rows].join('\r\n').concat('\r\n');
}

export function createPublicReadController(service: PublicReadService) {
  return {
    listCompetitions: wrapPublicHandler(async (request, response) => {
      const query = parseQuery(competitionListQuerySchema, request, response);

      if (!query) {
        return;
      }

      response.status(200).json(await service.listCompetitions(query));
    }),

    getCompetition: wrapPublicHandler(async (request, response) => {
      const competition = await service.getCompetition(getPathParameter(request, 'competitionId'));

      if (!competition) {
        sendNotFound(response, 'Competition');
        return;
      }

      response.status(200).json({
        data: competition,
      });
    }),

    listSeasons: wrapPublicHandler(async (request, response) => {
      const query = parseQuery(seasonListQuerySchema, request, response);

      if (!query) {
        return;
      }

      response.status(200).json(await service.listSeasons(query));
    }),

    getSeason: wrapPublicHandler(async (request, response) => {
      const season = await service.getSeason(getPathParameter(request, 'seasonId'));

      if (!season) {
        sendNotFound(response, 'Season');
        return;
      }

      response.status(200).json({
        data: season,
      });
    }),

    listFixtures: wrapPublicHandler(async (request, response) => {
      const query = parseQuery(fixtureListQuerySchema, request, response);

      if (!query) {
        return;
      }

      response.status(200).json(await service.listFixtures(query));
    }),

    getFixture: wrapPublicHandler(async (request, response) => {
