}

function escapeCsvCell(value: boolean | number | string | null): string {
  let text = value === null ? '' : String(value);

  // Prevent spreadsheet applications from interpreting public text as a formula.
  if (/^[=+\-@]/.test(text)) {
    text = `'${text}`;
  }

  return `"${text.replaceAll('"', '""')}"`;
