              },
            }
          : {}),
      });

      return {
        data: page.records,
        pagination: {
          nextCursor: createNextCursor(page.hasMore, page.records, (record) => ({
            fixtureId: record.fixtureId,
            inningsOrdinal: record.inningsOrdinal,
