export async function requestPublicApi<ResponseBody>(
  path: string,
  schema: ResponseSchema<ResponseBody>,
  signal?: AbortSignal,
): Promise<ResponseBody> {
  const response = await fetch(`${apiBaseUrl}${path}`, {
    headers: {
      Accept: 'application/json',
    },
    signal: signal ?? null,
  });
  const body = await readResponseBody(response);

  if (!response.ok) {
    const errorResponse = apiErrorResponseSchema.safeParse(body);
    const message = errorResponse.success ? errorResponse.data.error.message : undefined;
    throw new ApiResponseError(response.status, message);
  }

  try {
    return schema.parse(body);
  } catch {
    throw new ApiContractError();
  }
}

export async function downloadFixtureEventExport(
  fixtureId: string,
  format: FixtureEventExportFormat,
  filters: FixtureEventExportFilters,
): Promise<Blob> {
  const parameters = new URLSearchParams();
  for (const [name, value] of Object.entries(filters)) {
    if (value) {
      parameters.set(name, value);
    }
  }
  const search = parameters.size > 0 ? `?${parameters.toString()}` : '';
  const response = await fetch(
    `${apiBaseUrl}/fixtures/${encodeURIComponent(fixtureId)}/events/export.${format}${search}`,
    { headers: { Accept: format === 'csv' ? 'text/csv' : 'application/json' } },
  );

  if (!response.ok) {
    const body = await readResponseBody(response);
    const errorResponse = apiErrorResponseSchema.safeParse(body);
    throw new ApiResponseError(
      response.status,
      errorResponse.success ? errorResponse.data.error.message : undefined,
    );
  }

  return response.blob();
}

export function datasetReleaseArtifactUrl(version: string): string {
  return `${apiBaseUrl}/dataset-releases/${encodeURIComponent(version)}/artifact.json`;
}

import { competitionCollectionResponseSchema } from '@sport-analytics/contracts';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { ApiResponseError } from './client';
import { ApiContractError, requestPublicApi } from './public-read';

function response(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: vi.fn().mockResolvedValue(body),
  } as unknown as Response;
}

describe('public read API client', () => {
  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it('requests and validates public data without an authorization header', async () => {
    const fetchMock = vi.fn().mockResolvedValue(
      response(200, {
        data: [{ competitionId: 'competition-1', name: 'Premier League' }],
        pagination: { nextCursor: null },
      }),
    );
    vi.stubGlobal('fetch', fetchMock);

    const result = await requestPublicApi(
      '/competitions?name=Premier',
      competitionCollectionResponseSchema,
    );

    expect(result.data[0]?.name).toBe('Premier League');
    expect(fetchMock).toHaveBeenCalledWith(
      'http://localhost:3000/api/v1/competitions?name=Premier',
      expect.objectContaining({
        headers: { Accept: 'application/json' },
      }),
    );
    const request = fetchMock.mock.calls[0]?.[1] as RequestInit;
    expect(new Headers(request.headers).has('Authorization')).toBe(false);
  });

  it('exposes a safe backend error message and status', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(
        response(400, {
          error: { code: 'INVALID_QUERY', message: 'The fixture filters are invalid.' },
        }),
      ),
    );

    const request = requestPublicApi('/fixtures?limit=0', competitionCollectionResponseSchema);

    await expect(request).rejects.toBeInstanceOf(ApiResponseError);
    await expect(request).rejects.toMatchObject({
      message: 'The fixture filters are invalid.',
      status: 400,
    });
  });

  it('rejects a successful response that violates the shared contract', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(response(200, { data: [{ privateAccountEmail: 'private@test' }] })),
    );

    await expect(
      requestPublicApi('/competitions', competitionCollectionResponseSchema),
    ).rejects.toBeInstanceOf(ApiContractError);
  });
