    return {
      ...common,
      state: 'rejected',
      rejectionCode: 'EVENT_SCHEMA_INVALID',
      rejectionMessage: parsed.error.issues[0]?.message ?? 'Event failed authoritative validation.',
      rejectionDetail: {
        issues: parsed.error.issues.map((issue) => ({
