      client,
      `
        INSERT INTO statistics_refresh_dependency (
          source_event_id,
          delivery_revision,
          fixture_id,
          scope,
          participant_id,
          competition_id,
          season
        )
        VALUES ($1::uuid, $2, $3, $4, $5, $6, $7)
      `,
      [
        sourceEventId,
        revision,
        dependency.fixtureId,
        dependency.scope,
        dependency.participantId,
        dependency.competitionId,
        dependency.season,
      ],
    );
  }
}

