            FROM batch_validation_result v
            WHERE v.batch_id = $1::bigint
              AND v.active
              AND COALESCE(v.source_ordinal, subjects.ordinal) = subjects.ordinal
              AND (v.batch_item_id IS NULL OR v.batch_item_id = i.batch_item_id)
