CREATE FUNCTION prevent_batch_provenance_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'Batch and batch-item provenance records cannot be deleted.'
        USING ERRCODE = '23514';
END;
$$;

CREATE TRIGGER batch_prevent_delete
    BEFORE DELETE ON batch
    FOR EACH ROW
    EXECUTE FUNCTION prevent_batch_provenance_delete();

CREATE TABLE batch_item (
    batch_item_id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    batch_id           bigint NOT NULL REFERENCES batch (batch_id) ON DELETE RESTRICT,
    ordinal            integer NOT NULL,
    innings_id         bigint NOT NULL REFERENCES innings (innings_id) ON DELETE RESTRICT,
    over_number        smallint NOT NULL,
    position_in_over   smallint NOT NULL,
    payload            jsonb NOT NULL,
    state              batch_item_state NOT NULL DEFAULT 'pending',
    rejection_code     text,
    rejection_detail   jsonb,
    published_event_id bigint REFERENCES delivery (delivery_id) ON DELETE RESTRICT,

    CONSTRAINT batch_item_batch_ordinal_key UNIQUE (batch_id, ordinal),
    CONSTRAINT batch_item_batch_natural_key UNIQUE (
        batch_id,
        innings_id,
        over_number,
        position_in_over
    ),
    CONSTRAINT batch_item_ordinal_ck CHECK (ordinal >= 0),
    CONSTRAINT batch_item_over_number_ck CHECK (over_number >= 0),
    CONSTRAINT batch_item_position_in_over_ck CHECK (position_in_over >= 0),
    CONSTRAINT batch_item_published_event_ck CHECK (
        state <> 'published' OR published_event_id IS NOT NULL
    )
);

COMMENT ON TABLE batch_item IS
    'One expanded payload event, ordered by its zero-based payload ordinal and retained before publication.';

COMMENT ON COLUMN batch_item.position_in_over IS
    'The delivery natural-key position. Printed ballNumber remains payload display data and is not an identity column.';

COMMENT ON COLUMN batch_item.published_event_id IS
    'Delivery revision created when this staged item is published.';

CREATE TRIGGER batch_item_prevent_delete
    BEFORE DELETE ON batch_item
    FOR EACH ROW
    EXECUTE FUNCTION prevent_batch_provenance_delete();

CREATE TABLE batch_checkpoint (
    batch_id          bigint PRIMARY KEY REFERENCES batch (batch_id) ON DELETE RESTRICT,
    phase             batch_checkpoint_phase NOT NULL,
    last_ordinal      integer NOT NULL,
    lease_owner       text,
    lease_expires_at  timestamptz,
    attempt_count     integer NOT NULL DEFAULT 0,

    CONSTRAINT batch_checkpoint_last_ordinal_ck CHECK (last_ordinal >= 0),
    CONSTRAINT batch_checkpoint_lease_ck CHECK (
        (lease_owner IS NULL) = (lease_expires_at IS NULL)
        AND (lease_owner IS NULL OR length(btrim(lease_owner)) > 0)
    ),
---extended---
-- Up Migration
--
-- Persistence-only gaps identified for #277-#284 after auditing the #276 batch,
-- batch_item and batch_checkpoint foundation. This migration deliberately adds
-- no worker, validation, review, state-transition, or publication behaviour.
--
-- Refs #359

CREATE TYPE batch_reference_resolution_state AS ENUM (
    'unresolved',
    'resolved',
    'ambiguous',
    'invalid'
);

CREATE TYPE batch_validation_severity AS ENUM ('error', 'warning');

CREATE TYPE batch_review_decision_kind AS ENUM ('approved', 'rejected');

ALTER TABLE batch
    ADD COLUMN package_version text NOT NULL DEFAULT '1.0',
    ADD CONSTRAINT batch_package_version_ck CHECK (length(btrim(package_version)) > 0);

COMMENT ON COLUMN batch.package_version IS
    'Version declared by the received batch package; independent from the delivery-event schema version.';

ALTER TABLE batch_item
    ALTER COLUMN innings_id DROP NOT NULL,
    ADD COLUMN source_identity text,
    ADD COLUMN source_location jsonb,
    ADD COLUMN reference_resolution_state batch_reference_resolution_state NOT NULL DEFAULT 'resolved',
    ADD COLUMN resolved_references jsonb,
    ADD CONSTRAINT batch_item_source_identity_ck CHECK (
        source_identity IS NULL OR length(btrim(source_identity)) > 0
    ),
    ADD CONSTRAINT batch_item_source_location_ck CHECK (
        source_location IS NULL OR jsonb_typeof(source_location) = 'object'
    ),
    ADD CONSTRAINT batch_item_resolved_references_ck CHECK (
        resolved_references IS NULL OR jsonb_typeof(resolved_references) = 'object'
    );

CREATE UNIQUE INDEX batch_item_source_identity_key
    ON batch_item (batch_id, source_identity)
    WHERE source_identity IS NOT NULL;

COMMENT ON COLUMN batch_item.source_identity IS
    'Stable externally supplied delivery identity, unique within the received batch when present.';

COMMENT ON COLUMN batch_item.source_location IS
    'Normalised source location such as file, record/row and field path; never an application database key.';

COMMENT ON COLUMN batch_item.reference_resolution_state IS
    'Outcome of resolving submitted fixture, innings, team and participant references.';

COMMENT ON COLUMN batch_item.resolved_references IS
    'Provenance mapping from submitted references to canonical records or resolution candidates.';

CREATE TABLE batch_validation_result (
    batch_validation_result_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    batch_id                   bigint NOT NULL REFERENCES batch (batch_id) ON DELETE RESTRICT,
    batch_item_id              bigint REFERENCES batch_item (batch_item_id) ON DELETE RESTRICT,
    source_ordinal             integer,
    rule_code                  text NOT NULL,
    rule_version               text NOT NULL,
    severity                   batch_validation_severity NOT NULL,
    file_path                  text,
    row_number                 integer,
    field_path                 text,
    message                    text NOT NULL,
    created_at                 timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT batch_validation_result_subject_ck CHECK (
        batch_item_id IS NOT NULL OR source_ordinal IS NOT NULL
    ),
    CONSTRAINT batch_validation_result_source_ordinal_ck CHECK (
        source_ordinal IS NULL OR source_ordinal >= 0
    ),
    CONSTRAINT batch_validation_result_rule_code_ck CHECK (length(btrim(rule_code)) > 0),
    CONSTRAINT batch_validation_result_rule_version_ck CHECK (length(btrim(rule_version)) > 0),
    CONSTRAINT batch_validation_result_file_path_ck CHECK (
        file_path IS NULL OR length(btrim(file_path)) > 0
    ),
    CONSTRAINT batch_validation_result_row_number_ck CHECK (
        row_number IS NULL OR row_number > 0
    ),
    CONSTRAINT batch_validation_result_field_path_ck CHECK (
        field_path IS NULL OR length(btrim(field_path)) > 0
    ),
    CONSTRAINT batch_validation_result_message_ck CHECK (length(btrim(message)) > 0)
);

CREATE UNIQUE INDEX batch_validation_result_deterministic_key
    ON batch_validation_result (
        batch_id,
        COALESCE(batch_item_id, 0),
        COALESCE(source_ordinal, -1),
        rule_code,
        rule_version,
        severity,
        COALESCE(file_path, ''),
        COALESCE(row_number, -1),
        COALESCE(field_path, '')
    );

CREATE TRIGGER batch_validation_result_prevent_delete
    BEFORE DELETE ON batch_validation_result
    FOR EACH ROW
    EXECUTE FUNCTION prevent_batch_provenance_delete();

COMMENT ON TABLE batch_validation_result IS
    'Immutable, structured result of one validation or reference-resolution rule for a staged batch source location.';

ALTER TABLE batch_checkpoint
    DROP CONSTRAINT batch_checkpoint_pkey,
    ADD PRIMARY KEY (batch_id, phase);

COMMENT ON TABLE batch_checkpoint IS
    'Independent durable validation and publication checkpoints, each with its own worker lease and attempt count.';

CREATE TABLE batch_review_decision (
    batch_review_decision_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    batch_id                 bigint NOT NULL REFERENCES batch (batch_id) ON DELETE RESTRICT,
    actor_id                 bigint NOT NULL REFERENCES app_user (app_user_id) ON DELETE RESTRICT,
    decision                 batch_review_decision_kind NOT NULL,
    reason                   text,
    decided_at               timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT batch_review_decision_reason_ck CHECK (
        reason IS NULL OR length(btrim(reason)) > 0
    )
);

CREATE TRIGGER batch_review_decision_prevent_delete
    BEFORE DELETE ON batch_review_decision
    FOR EACH ROW
    EXECUTE FUNCTION prevent_batch_provenance_delete();

COMMENT ON TABLE batch_review_decision IS
    'Append-only review provenance. Applying a decision to lifecycle state is a later workflow concern.';

ALTER TABLE delivery
    ADD COLUMN source_batch_item_id bigint REFERENCES batch_item (batch_item_id) ON DELETE RESTRICT;

CREATE UNIQUE INDEX delivery_source_batch_item_key
    ON delivery (source_batch_item_id)
    WHERE source_batch_item_id IS NOT NULL;

COMMENT ON COLUMN delivery.source_batch_item_id IS
    'The immutable staged batch item from which this delivery revision was published.';

-- Down Migration

DROP INDEX IF EXISTS delivery_source_batch_item_key;
ALTER TABLE delivery DROP COLUMN IF EXISTS source_batch_item_id;

DROP TRIGGER IF EXISTS batch_review_decision_prevent_delete ON batch_review_decision;
DROP TABLE IF EXISTS batch_review_decision;

ALTER TABLE batch_checkpoint
    DROP CONSTRAINT IF EXISTS batch_checkpoint_pkey,
    ADD PRIMARY KEY (batch_id);

DROP TRIGGER IF EXISTS batch_validation_result_prevent_delete ON batch_validation_result;
DROP INDEX IF EXISTS batch_validation_result_deterministic_key;
DROP TABLE IF EXISTS batch_validation_result;

DROP INDEX IF EXISTS batch_item_source_identity_key;
ALTER TABLE batch_item
    DROP CONSTRAINT IF EXISTS batch_item_resolved_references_ck,
    DROP CONSTRAINT IF EXISTS batch_item_source_location_ck,
    DROP CONSTRAINT IF EXISTS batch_item_source_identity_ck,
    DROP COLUMN IF EXISTS resolved_references,
    DROP COLUMN IF EXISTS reference_resolution_state,
    DROP COLUMN IF EXISTS source_location,
    DROP COLUMN IF EXISTS source_identity;
---history DDL---
-- Up Migration
--
-- Immutable event-correction lineage and audit history.
--
-- Refs #284

DROP INDEX IF EXISTS delivery_source_event_id_unique;
DROP INDEX IF EXISTS delivery_submission_event_order_unique;
DROP INDEX IF EXISTS delivery_source_batch_item_key;

CREATE UNIQUE INDEX delivery_source_event_revision_unique
    ON delivery (source_event_id, revision)
    WHERE source_event_id IS NOT NULL;

CREATE UNIQUE INDEX delivery_submission_event_revision_unique
    ON delivery (submission_id, submission_event_ordinal, revision)
    WHERE submission_event_ordinal IS NOT NULL;

CREATE UNIQUE INDEX delivery_source_batch_item_revision_unique
    ON delivery (source_batch_item_id, revision)
    WHERE source_batch_item_id IS NOT NULL;

ALTER TABLE delivery
    ADD COLUMN supersedes_delivery_id bigint REFERENCES delivery (delivery_id) ON DELETE RESTRICT;

-- Earlier correction code retained the forward delivery link but cleared the
-- predecessor's direct-submission identity to satisfy the old global unique
-- indexes. Recover that attributable provenance from the current revision and
-- its forward-linked chain before enforcing the stronger invariants.
WITH RECURSIVE revision_lineage AS (
    SELECT
        delivery_id,
        source_event_id,
        submission_id,
        submission_event_ordinal,
        source_batch_item_id
    FROM delivery
    WHERE superseded_at IS NULL
      AND source_event_id IS NOT NULL

    UNION ALL

    SELECT
        previous.delivery_id,
        lineage.source_event_id,
        lineage.submission_id,
        lineage.submission_event_ordinal,
        COALESCE(previous.source_batch_item_id, lineage.source_batch_item_id)
    FROM delivery previous
    JOIN revision_lineage lineage ON previous.superseded_by = lineage.delivery_id
    WHERE previous.delivery_id <> previous.superseded_by
)
UPDATE delivery target
SET source_event_id = lineage.source_event_id,
    submission_id = lineage.submission_id,
    submission_event_ordinal = lineage.submission_event_ordinal,
    source_batch_item_id = lineage.source_batch_item_id
FROM revision_lineage lineage
WHERE target.delivery_id = lineage.delivery_id;

UPDATE delivery replacement
SET supersedes_delivery_id = previous.delivery_id
FROM delivery previous
WHERE previous.superseded_by = replacement.delivery_id
  AND previous.delivery_id <> replacement.delivery_id;

ALTER TABLE delivery
    ADD CONSTRAINT delivery_revision_lineage_ck CHECK (
        (revision = 1 AND supersedes_delivery_id IS NULL)
        OR (revision > 1 AND supersedes_delivery_id IS NOT NULL)
    ),
    ADD CONSTRAINT delivery_revision_positive_ck CHECK (revision > 0),
    ADD CONSTRAINT delivery_not_self_superseding_ck CHECK (
        supersedes_delivery_id IS NULL OR supersedes_delivery_id <> delivery_id
    );

CREATE UNIQUE INDEX delivery_supersedes_revision_unique
    ON delivery (supersedes_delivery_id)
    WHERE supersedes_delivery_id IS NOT NULL;

CREATE FUNCTION protect_delivery_revision()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF (to_jsonb(NEW) - ARRAY['superseded_at', 'superseded_by', 'source_batch_item_id'])
       IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['superseded_at', 'superseded_by', 'source_batch_item_id']) THEN
        RAISE EXCEPTION 'Published delivery revision content and provenance cannot be overwritten.'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.source_batch_item_id IS NOT NULL
       AND NEW.source_batch_item_id IS DISTINCT FROM OLD.source_batch_item_id THEN
        RAISE EXCEPTION 'Published delivery source-item provenance cannot be changed.'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.superseded_at IS NOT NULL
       AND (NEW.superseded_at IS DISTINCT FROM OLD.superseded_at
            OR NEW.superseded_by IS DISTINCT FROM OLD.superseded_by)
       AND NOT (
           OLD.superseded_by = OLD.delivery_id
           AND NEW.superseded_at = OLD.superseded_at
           AND NEW.superseded_by <> OLD.delivery_id
       ) THEN
        RAISE EXCEPTION 'Superseded delivery lineage cannot be changed.'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER delivery_protect_revision
    BEFORE UPDATE ON delivery
    FOR EACH ROW
    EXECUTE FUNCTION protect_delivery_revision();

CREATE FUNCTION validate_delivery_revision_lineage()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    previous delivery%ROWTYPE;
BEGIN
    IF NEW.revision = 1 THEN
        RETURN NEW;
    END IF;

    SELECT * INTO previous
    FROM delivery
    WHERE delivery_id = NEW.supersedes_delivery_id;

    IF NOT FOUND
       OR previous.revision + 1 <> NEW.revision
       OR previous.source_event_id IS DISTINCT FROM NEW.source_event_id
       OR previous.submission_id IS DISTINCT FROM NEW.submission_id
       OR previous.submission_event_ordinal IS DISTINCT FROM NEW.submission_event_ordinal
       OR previous.source_batch_item_id IS DISTINCT FROM NEW.source_batch_item_id
       OR previous.innings_sequence IS DISTINCT FROM NEW.innings_sequence THEN
        RAISE EXCEPTION 'A delivery revision must preserve provenance and occurrence sequence and increment its predecessor revision by one.'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER delivery_validate_revision_lineage
    BEFORE INSERT ON delivery
    FOR EACH ROW
    EXECUTE FUNCTION validate_delivery_revision_lineage();

CREATE TABLE delivery_correction_history (
    delivery_correction_history_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    source_event_id                uuid NOT NULL,
    previous_delivery_id           bigint NOT NULL UNIQUE REFERENCES delivery (delivery_id) ON DELETE RESTRICT,
    replacement_delivery_id        bigint NOT NULL UNIQUE REFERENCES delivery (delivery_id) ON DELETE RESTRICT,
    requester_id                   bigint NOT NULL REFERENCES app_user (app_user_id) ON DELETE RESTRICT,
    requested_at                   timestamptz NOT NULL DEFAULT now(),
    reason                         text NOT NULL,
    previous_state                 jsonb NOT NULL,
    resulting_state                jsonb NOT NULL,
    original_submission_id         bigint NOT NULL REFERENCES submission (submission_id) ON DELETE RESTRICT,
    original_submission_ordinal    integer,
    original_batch_item_id         bigint REFERENCES batch_item (batch_item_id) ON DELETE RESTRICT,
    reviewer_id                    bigint REFERENCES app_user (app_user_id) ON DELETE RESTRICT,
    review_decision                batch_review_decision_kind,
    reviewed_at                    timestamptz,
    review_reason                  text,

