  return z
    .object({
      sourceId: sourceIdentifierFor(entityType).optional(),
      context: context.optional(),
    })
    .strict()
    .superRefine((reference, issueContext) => {
      if (!reference.sourceId && !reference.context) {
        issueContext.addIssue({
