    try {
      fields = splitCsvRecord(record);
    } catch (error) {
      faults.push({
        sourceOrdinal: ordinal,
        ruleCode: 'CSV_MALFORMED_ROW',
        filePath: 'batch.csv',
        rowNumber,
        fieldPath: null,
        message: safeMessage(error),
        countsAsItem: true,
      });
      ordinal += 1;
      if (ordinal > MAX_BATCH_ITEMS)
        throw new Error(`Batch exceeds the ${String(MAX_BATCH_ITEMS)}-item limit.`);
      continue;
    }
